// components/Sidebar.js
import React from 'react';

const Sidebar = ({ 
  currentPage, 
  currentUserRole, 
  onNavigate, 
  onLogout, 
  menuPages, 
  pageKeys, 
  getIcon,
  isOpen,
  onClose
}) => {
  const USER_ROLES = {
    admin: { name: "Admin" },
    manager: { name: "Manager" }
  };

  const handleNavClick = (page) => {
    onNavigate(page);
    if (window.innerWidth <= 768) {
      onClose();
    }
  };

  return (
    <div className={`sidebar ${isOpen ? 'open' : ''}`}>
      <div className="logo">
        <i className="fas fa-bolt"></i>
        <span>JamiiSim</span>
      </div>
      <nav>
        <ul>
          {menuPages.map(page => (
            <li key={page}>
              <button 
                className={currentPage === pageKeys[page] ? 'active' : ''}
                onClick={() => handleNavClick(pageKeys[page])}
              >
                <i className={`fas ${getIcon(pageKeys[page])}`}></i>
                <span>{page}</span>
              </button>
            </li>
          ))}
          <li style={{ marginTop: '2rem' }}>
            <button onClick={onLogout}>
              <i className="fas fa-sign-out-alt"></i>
              <span>Logout</span>
            </button>
          </li>
        </ul>
      </nav>
      <div className="user-badge">
        <i className="fas fa-user-shield"></i> 
        {USER_ROLES[currentUserRole]?.name || currentUserRole}
      </div>
    </div>
  );
};

export default Sidebar;
